(()=>{
const $=s=>document.querySelector(s);
const els={
  wcBtn:$('#walletConnect'), evmBtn:$('#browserWalletConnect'), btcBtn:$('#bitcoinWalletConnect'),
  solBtn:$('#solanaWalletConnect'), tronBtn:$('#tronWalletConnect'),
  state:$('#walletState'), message:$('#walletMessage'), snapshot:$('#walletSnapshot'),
  address:$('#walletAddress'), network:$('#walletNetwork'), chain:$('#walletChain'), balance:$('#walletBalance'),
  balanceNote:$('#walletBalanceNote'), walletName:$('#walletProviderName'), detailTitle:$('#walletDetailTitle'),
  tokenList:$('#walletTokenList'), historyList:$('#walletHistoryList'), historyStatus:$('#walletHistoryStatus'),
  historyRefresh:$('#walletHistoryRefresh'), evmTokensSection:$('#evmTokensSection'), evmHistorySection:$('#evmHistorySection'),
  project:$('#walletProjectStatus'), relay:$('#walletRelayStatus'), disconnect:$('#walletDisconnect'),
  saved:$('#savedWallets'), savedCount:$('#savedWalletCount'), savedRefresh:$('#refreshSavedWallets'),
  qrModal:$('#walletQrModal'), qrImage:$('#walletQrImage'), qrLoading:$('#walletQrLoading'),
  qrClose:$('#walletQrClose'), qrCancel:$('#walletQrCancel'), qrCopy:$('#walletQrCopy')
};

const WC_GLOBAL=window['@walletconnect/ethereum-provider']||{};
const EthereumProvider=WC_GLOBAL.EthereumProvider||WC_GLOBAL.default?.EthereumProvider||WC_GLOBAL.default;
const EVM_CHAINS={1:{name:'Ethereum',symbol:'ETH'},10:{name:'Optimism',symbol:'ETH'},56:{name:'BNB Smart Chain',symbol:'BNB'},137:{name:'Polygon',symbol:'POL'},8453:{name:'Base',symbol:'ETH'},42161:{name:'Arbitrum One',symbol:'ETH'}};
const OPTIONAL_CHAINS=Object.keys(EVM_CHAINS).map(Number);
const TOKENS={
  1:[{symbol:'USDT',address:'0xdAC17F958D2ee523a2206206994597C13D831ec7',decimals:6}],
  10:[{symbol:'USDT',address:'0x94b008aA00579c1307B0EF2c499aD98a8ce58e58',decimals:6}],
  56:[{symbol:'USDT',address:'0x55d398326f99059fF775485246999027B3197955',decimals:18}],
  137:[{symbol:'USDT',address:'0xc2132D05D31c914a87C6611C10748AaCbFfEFeD',decimals:6}],
  42161:[{symbol:'USDT',address:'0xFd086bC7CD5C481DCC9C85ebe478A1C0b69FCbb9',decimals:6}]
};
const NS_LABELS={eip155:'EVM',bip122:'Bitcoin',solana:'Solana',tron:'TRON'};

let wc=null,active={namespace:null,address:null,provider:null,walletName:null,chainId:null,providerType:null};
let currentPairingUri='',pairingQrUrl='',connectTimer=null;

function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function short(a){a=String(a||'');return a.length>18?`${a.slice(0,9)}…${a.slice(-7)}`:a||'—'}
function setMessage(msg,bad=false){if(!els.message)return;els.message.textContent=msg||'';els.message.classList.toggle('negative',!!bad);els.message.classList.toggle('positive',!bad&&!!msg)}
function setState(on,label){if(!els.state)return;els.state.textContent=label||(on?'Connected':'Not connected');els.state.classList.toggle('connected',!!on)}
function parseChainId(v){if(typeof v==='number')return v;const s=String(v||'');if(s.startsWith('0x'))return parseInt(s,16);if(s.includes(':'))return Number(s.split(':').pop());return Number(s)||0}
function formatUnitsBigInt(v,decimals){const n=BigInt(v||0),base=10n**BigInt(decimals),whole=n/base,frac=(n%base).toString().padStart(decimals,'0').slice(0,8).replace(/0+$/,'');return frac?`${whole}.${frac}`:String(whole)}
async function api(url,opt={}){const r=await fetch(url,{...opt,headers:{accept:'application/json',...(opt.headers||{})}});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||`Request failed (${r.status})`);return d}
async function savePublic({address,namespace,chainId,walletName,providerType}){await api('/api/integrations/wallet/status',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({address,namespace,chainId:String(chainId||''),walletName,providerType})})}
async function removePublic(namespace,address){await api(`/api/integrations/wallet/status?namespace=${encodeURIComponent(namespace)}&address=${encodeURIComponent(address)}`,{method:'DELETE'});await loadSavedWallets()}
function closePairingModal(){if(connectTimer){clearTimeout(connectTimer);connectTimer=null}if(els.qrModal)els.qrModal.hidden=true;if(pairingQrUrl){URL.revokeObjectURL(pairingQrUrl);pairingQrUrl=''}if(els.qrImage)els.qrImage.removeAttribute('src');if(els.qrLoading){els.qrLoading.hidden=false;els.qrLoading.textContent='Creating secure pairing code…'}}
async function showPairingUri(uri){currentPairingUri=String(uri||'');if(!currentPairingUri.startsWith('wc:'))return;if(els.qrModal)els.qrModal.hidden=false;try{const r=await fetch('/api/integrations/wallet/qr',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({uri:currentPairingUri})});if(!r.ok)throw new Error('Could not generate pairing QR.');const blob=await r.blob();if(pairingQrUrl)URL.revokeObjectURL(pairingQrUrl);pairingQrUrl=URL.createObjectURL(blob);els.qrImage.src=pairingQrUrl;els.qrLoading.hidden=true;connectTimer=setTimeout(()=>setMessage('WalletConnect pairing request expired. Close the QR and try again.',true),300000)}catch(e){els.qrLoading.textContent=e.message||'QR generation failed.'}}
function hideEvmSections(hide){els.evmTokensSection.hidden=hide;els.evmHistorySection.hidden=hide}
function showDetail({namespace,address,network,chainId,balance,walletName,balanceNote='Read-only balance',provider=null,providerType=''}){active={namespace,address,provider,walletName,chainId,providerType};els.snapshot.hidden=false;els.detailTitle.textContent=`${NS_LABELS[namespace]||'Wallet'} Wallet`;els.address.textContent=address;els.address.title=address;els.network.textContent=network||NS_LABELS[namespace]||'Connected';els.chain.textContent=String(chainId||'—');els.balance.textContent=balance??'—';els.balanceNote.textContent=balanceNote;els.walletName.textContent=walletName||'Wallet';hideEvmSections(namespace!=='eip155');setState(true,`${NS_LABELS[namespace]||'Wallet'} connected`)}
function clearDetail(){active={namespace:null,address:null,provider:null,walletName:null,chainId:null,providerType:null};els.snapshot.hidden=true;setState(false)}
function walletCard(x){return `<article class="saved-wallet-item"><div class="saved-wallet-badge">${esc(NS_LABELS[x.namespace]||x.namespace)}</div><div class="saved-wallet-copy"><b>${esc(x.wallet_name||'Wallet')}</b><code>${esc(short(x.address))}</code><small>${esc(x.chain_id||'')}</small></div><button class="btn" data-wallet-view="${esc(x.id)}">View</button><button class="btn danger" data-wallet-remove="${esc(x.id)}">Remove</button></article>`}
let savedConnections=[];
async function loadSavedWallets(){try{const d=await api('/api/integrations/wallet/status');savedConnections=d.connections||[];els.savedCount.textContent=savedConnections.length?`${savedConnections.length} connected wallet${savedConnections.length===1?'':'s'}`:'No saved wallet connections';els.saved.innerHTML=savedConnections.length?savedConnections.map(walletCard).join(''):'<div class="wallet-empty-mini">Connect a wallet above. Public connection details will appear here.</div>';els.saved.querySelectorAll('[data-wallet-remove]').forEach(b=>b.onclick=async()=>{const x=savedConnections.find(v=>String(v.id)===b.dataset.walletRemove);if(!x)return;if(!(await appConfirm(`Remove ${x.wallet_name||'this wallet'} from OptiTrade?`,{title:'Remove connected wallet',confirmText:'Remove',danger:true})))return;await removePublic(x.namespace,x.address);if(active.address===x.address&&active.namespace===x.namespace)clearDetail()});els.saved.querySelectorAll('[data-wallet-view]').forEach(b=>b.onclick=()=>{const x=savedConnections.find(v=>String(v.id)===b.dataset.walletView);if(!x)return;showDetail({namespace:x.namespace,address:x.address,network:NS_LABELS[x.namespace],chainId:x.chain_id,balance:'Reconnect for live balance',walletName:x.wallet_name,balanceNote:'Saved public connection'})})}catch(e){els.saved.innerHTML=`<div class="wallet-empty-mini">${esc(e.message)}</div>`}}
async function getEvmBalance(provider,address,chainId){try{const hex=await provider.request({method:'eth_getBalance',params:[address,'latest']});return `${(Number(BigInt(hex))/1e18).toLocaleString(undefined,{maximumFractionDigits:6})} ${EVM_CHAINS[chainId]?.symbol||'ETH'}`}catch{return 'Unavailable'}}
async function getTokenBalance(provider,address,token){const clean=address.toLowerCase().replace(/^0x/,'').padStart(64,'0'),data='0x70a08231'+clean;const raw=await provider.request({method:'eth_call',params:[{to:token.address,data},'latest']});return formatUnitsBigInt(raw,token.decimals)}
async function loadTrackedTokens(provider,address,chainId){const list=TOKENS[chainId]||[];if(!list.length){els.tokenList.innerHTML='<div class="wallet-empty-mini">No tracked token contracts are configured for this EVM network yet.</div>';return}els.tokenList.innerHTML='<div class="wallet-empty-mini">Loading tracked tokens…</div>';const rows=[];for(const token of list){try{rows.push({...token,balance:await getTokenBalance(provider,address,token)})}catch{rows.push({...token,balance:'Unavailable'})}}els.tokenList.innerHTML=rows.map(t=>`<div class="wallet-token-row"><b>${t.symbol}</b><span>${t.balance}</span><small>${t.address.slice(0,8)}…${t.address.slice(-6)}</small></div>`).join('')}
async function loadEvmHistory(chainId,address){els.historyStatus.textContent='Loading on-chain activity…';try{const d=await api(`/api/integrations/wallet/history?chainId=${encodeURIComponent(chainId)}&address=${encodeURIComponent(address)}`);if(!d.configured){els.historyStatus.textContent='History provider not configured yet.';els.historyList.innerHTML='<div class="wallet-empty-mini">Add ETHERSCAN_API_KEY on the server to show recent EVM transactions.</div>';return}const rows=d.transactions||[];els.historyStatus.textContent=rows.length?`Latest ${rows.length} activities`:'No recent activity found';els.historyList.innerHTML=rows.length?rows.map(x=>`<div class="wallet-history-row"><span class="wallet-history-dir ${x.direction}">${x.direction==='in'?'↓':'↑'}</span><div><b>${x.direction==='in'?'Received':'Sent'} ${esc(x.symbol)}</b><small>${new Date(x.time).toLocaleString()} • ${esc(x.hash.slice(0,10))}…${esc(x.hash.slice(-8))}</small></div><strong>${Number(x.amount).toLocaleString(undefined,{maximumFractionDigits:8})} ${esc(x.symbol)}</strong></div>`).join(''):'<div class="wallet-empty-mini">No recent transactions returned by the history provider.</div>'}catch(e){els.historyStatus.textContent='History unavailable';els.historyList.innerHTML=`<div class="wallet-empty-mini">${esc(e.message)}</div>`}}
async function renderEvm(provider,address,chainId,walletName,providerType){const cid=parseChainId(chainId),meta=EVM_CHAINS[cid]||{name:'EVM Network',symbol:'ETH'},balance=await getEvmBalance(provider,address,cid);await savePublic({address,namespace:'eip155',chainId:cid,walletName,providerType});showDetail({namespace:'eip155',address,network:meta.name,chainId:`Chain ID ${cid}`,balance,walletName,provider,balanceNote:'Live native balance',providerType});await Promise.all([loadTrackedTokens(provider,address,cid),loadEvmHistory(cid,address),loadSavedWallets()]);setMessage(`Connected ${short(address)} on ${meta.name}.`)}
function wireEvm(provider,walletName,providerType){if(!provider?.on)return;provider.on('accountsChanged',async a=>{if(a?.[0])await renderEvm(provider,a[0],parseChainId(provider.chainId||await provider.request({method:'eth_chainId'})),walletName,providerType);else clearDetail()});provider.on('chainChanged',async v=>{if(active.namespace==='eip155'&&active.address)await renderEvm(provider,active.address,parseChainId(v),walletName,providerType)})}
async function initWalletConnect(){if(!EthereumProvider||typeof EthereumProvider.init!=='function')throw new Error('WalletConnect browser provider did not load. Check internet access and refresh.');const cfg=await api('/api/integrations/wallet/config');if(!cfg.projectId)throw new Error('WalletConnect Project ID is not configured.');els.project.textContent='WalletConnect Project ID loaded';wc=await EthereumProvider.init({projectId:cfg.projectId,optionalChains:OPTIONAL_CHAINS,showQrModal:false,metadata:{name:'OptiTrade',description:'OptiTrade crypto wallet connection',url:location.origin,icons:[]},methods:['eth_accounts','eth_requestAccounts','eth_sendTransaction','personal_sign','eth_signTypedData','eth_signTypedData_v4'],events:['chainChanged','accountsChanged']});wc.on('display_uri',uri=>{els.relay.textContent='WalletConnect pairing ready';showPairingUri(uri)});wc.on('connect',()=>{els.relay.textContent='WalletConnect connected';closePairingModal()});wireEvm(wc,'WalletConnect','walletconnect')}
async function connectWalletConnect(){els.wcBtn.disabled=true;setMessage('Creating WalletConnect pairing request…');try{if(!wc)await initWalletConnect();await wc.connect({optionalChains:OPTIONAL_CHAINS});const raw=wc.accounts?.[0];if(!raw)throw new Error('Wallet did not return an EVM account.');const address=String(raw).includes(':')?String(raw).split(':').pop():raw;closePairingModal();await renderEvm(wc,address,parseChainId(wc.chainId),'WalletConnect','walletconnect')}catch(e){setMessage(e.message||String(e),true);els.relay.textContent='WalletConnect connection failed'}finally{els.wcBtn.disabled=false}}
async function connectBrowserEvm(){const p=window.ethereum;if(!p)return setMessage('No injected EVM wallet was detected. Try WalletConnect QR or open OptiTrade inside your wallet browser.',true);els.evmBtn.disabled=true;try{const a=await p.request({method:'eth_requestAccounts'});if(!a?.[0])throw new Error('Wallet did not return an account.');const cid=parseChainId(await p.request({method:'eth_chainId'})),name=p.isMetaMask?'MetaMask':p.isCoinbaseWallet?'Coinbase Wallet':'Browser EVM Wallet';wireEvm(p,name,'injected');await renderEvm(p,a[0],cid,name,'injected')}catch(e){setMessage(e.message||String(e),true)}finally{els.evmBtn.disabled=false}}

function detectBitcoinWallet(){
 if(window.unisat)return {provider:window.unisat,name:'UniSat',type:'unisat'};
 if(window.okxwallet?.bitcoin)return {provider:window.okxwallet.bitcoin,name:'OKX Bitcoin Wallet',type:'okx'};
 if(window.XverseProviders?.BitcoinProvider)return {provider:window.XverseProviders.BitcoinProvider,name:'Xverse Wallet',type:'xverse'};
 if(window.BitcoinProvider)return {provider:window.BitcoinProvider,name:'Bitcoin Wallet',type:'generic'};
 return null;
}
async function connectBitcoin(){const w=detectBitcoinWallet();if(!w)return setMessage('No supported Bitcoin wallet was detected. Install/open UniSat, OKX Bitcoin, Xverse, or use that wallet’s in-app browser.',true);els.btcBtn.disabled=true;try{let address='',network='Bitcoin Mainnet',balance='Unavailable';if(w.type==='xverse'||w.type==='generic'){if(typeof w.provider.request!=='function')throw new Error('Detected Bitcoin provider does not expose a compatible connection method.');const r=await w.provider.request('wallet_connect',null);const result=r?.result||r;const rows=result?.addresses||result?.addressses||[];const payment=rows.find(x=>x.purpose==='payment')||rows[0];address=payment?.address||'';network=result?.network?.bitcoin?.name||payment?.network||network;try{const b=await w.provider.request('getBalance',null);const br=b?.result||b;if(br?.total!=null)balance=`${(Number(br.total)/1e8).toLocaleString(undefined,{maximumFractionDigits:8})} BTC`}catch{}}else{let accounts=[];if(typeof w.provider.requestAccounts==='function')accounts=await w.provider.requestAccounts();else if(typeof w.provider.connect==='function'){const r=await w.provider.connect();accounts=[r?.address].filter(Boolean)}if(!accounts?.[0])throw new Error('Bitcoin wallet did not return an account.');address=accounts[0];try{const c=typeof w.provider.getChain==='function'?await w.provider.getChain():typeof w.provider.getNetwork==='function'?await w.provider.getNetwork():null;network=c?.name||c?.network||c||network}catch{}try{const b=await w.provider.getBalance();const sat=Number(b?.total??b?.confirmed??0);balance=`${(sat/1e8).toLocaleString(undefined,{maximumFractionDigits:8})} BTC`}catch{}}if(!address)throw new Error('Bitcoin payment address was not returned.');await savePublic({address,namespace:'bip122',chainId:String(network),walletName:w.name,providerType:w.type});showDetail({namespace:'bip122',address,network:String(network),chainId:'Bitcoin',balance,walletName:w.name,provider:w.provider,balanceNote:'Wallet-reported BTC balance',providerType:w.type});await loadSavedWallets();setMessage(`${w.name} connected: ${short(address)}.`);if(w.provider?.on){w.provider.on('accountsChanged',()=>setMessage('Bitcoin account changed. Reconnect to refresh the saved address.'));w.provider.on('networkChanged',()=>setMessage('Bitcoin network changed. Reconnect to refresh the saved network.'))}}catch(e){setMessage(e.message||String(e),true)}finally{els.btcBtn.disabled=false}}

function detectSolanaWallet(){if(window.phantom?.solana)return {provider:window.phantom.solana,name:'Phantom'};if(window.solflare)return {provider:window.solflare,name:'Solflare'};if(window.solana)return {provider:window.solana,name:window.solana.isPhantom?'Phantom':'Solana Wallet'};return null}
async function connectSolana(){const w=detectSolanaWallet();if(!w)return setMessage('No injected Solana wallet was detected. Open OptiTrade inside Phantom/Solflare’s in-app browser or install its browser extension.',true);els.solBtn.disabled=true;try{const r=await w.provider.connect();const pk=r?.publicKey||w.provider.publicKey,address=pk?.toString?.()||String(pk||'');if(!address)throw new Error('Solana wallet did not return a public address.');await savePublic({address,namespace:'solana',chainId:'mainnet',walletName:w.name,providerType:'injected'});let balance='Unavailable';try{const b=await api(`/api/integrations/wallet/native-balance?namespace=solana&address=${encodeURIComponent(address)}`);balance=`${Number(b.amount).toLocaleString(undefined,{maximumFractionDigits:8})} SOL`}catch{}showDetail({namespace:'solana',address,network:'Solana Mainnet',chainId:'mainnet',balance,walletName:w.name,provider:w.provider,balanceNote:'Confirmed SOL balance',providerType:'injected'});await loadSavedWallets();setMessage(`${w.name} connected: ${short(address)}.`);w.provider.on?.('accountChanged',async key=>{if(key){setMessage('Solana account changed. Reconnect to refresh the saved address.')}else clearDetail()})}catch(e){setMessage(e.message||String(e),true)}finally{els.solBtn.disabled=false}}

function detectTron(){if(window.tron?.isTronLink)return {provider:window.tron,name:'TronLink'};if(window.tronLink)return {provider:window.tronLink,name:'TronLink'};return null}
async function connectTron(){const w=detectTron();if(!w)return setMessage('TronLink was not detected. Install TronLink or open OptiTrade inside its supported DApp browser.',true);els.tronBtn.disabled=true;try{let accounts=[];try{accounts=await w.provider.request({method:'eth_requestAccounts'})}catch{try{const legacy=await w.provider.request({method:'tron_requestAccounts'});if(legacy?.code&&legacy.code!==200)throw new Error(legacy.message||'TronLink authorization failed.')}catch(e){throw e}}const tw=w.provider.tronWeb||window.tronWeb;const address=accounts?.[0]||tw?.defaultAddress?.base58||'';if(!address)throw new Error('TronLink did not return an authorized TRON address. Unlock the wallet and approve OptiTrade.');let balance='Unavailable';try{const sun=await tw.trx.getBalance(address);balance=`${(Number(sun)/1e6).toLocaleString(undefined,{maximumFractionDigits:6})} TRX`}catch{}await savePublic({address,namespace:'tron',chainId:'mainnet',walletName:w.name,providerType:'tronlink'});showDetail({namespace:'tron',address,network:'TRON Mainnet',chainId:'mainnet',balance,walletName:w.name,provider:w.provider,balanceNote:'Wallet-reported TRX balance',providerType:'tronlink'});await loadSavedWallets();setMessage(`TronLink connected: ${short(address)}.`);w.provider.on?.('accountsChanged',()=>setMessage('TRON account changed. Reconnect to refresh the saved address.'));w.provider.on?.('chainChanged',()=>setMessage('TRON network changed. Reconnect to refresh the network.'))}catch(e){setMessage(e.message||String(e),true)}finally{els.tronBtn.disabled=false}}

async function removeActive(){if(!active.namespace||!active.address)return;const n=active.namespace,a=active.address;if(active.namespace==='eip155'&&active.providerType==='walletconnect'&&wc){try{await wc.disconnect()}catch{}}await removePublic(n,a);clearDetail();setMessage('Wallet removed from OptiTrade. Wallet permissions can also be managed inside the wallet app.')}
els.wcBtn?.addEventListener('click',connectWalletConnect);
els.evmBtn?.addEventListener('click',connectBrowserEvm);
els.btcBtn?.addEventListener('click',connectBitcoin);
els.solBtn?.addEventListener('click',connectSolana);
els.tronBtn?.addEventListener('click',connectTron);
els.disconnect?.addEventListener('click',removeActive);
els.savedRefresh?.addEventListener('click',loadSavedWallets);
els.qrClose?.addEventListener('click',closePairingModal);
els.qrCancel?.addEventListener('click',()=>{closePairingModal();setMessage('Wallet connection cancelled.')});
els.qrModal?.addEventListener('click',e=>{if(e.target===els.qrModal)closePairingModal()});
els.qrCopy?.addEventListener('click',async()=>{if(!currentPairingUri)return;try{await navigator.clipboard.writeText(currentPairingUri);setMessage('Pairing link copied. Open it from a WalletConnect-compatible wallet.')}catch{setMessage('Could not copy the pairing link. Scan the QR instead.',true)}});
els.historyRefresh?.addEventListener('click',async()=>{if(active.namespace!=='eip155'||!active.address)return setMessage('EVM history is available only when an EVM wallet is active.',true);await loadEvmHistory(parseChainId(active.chainId),active.address)});

(async()=>{try{const me=await fetch('/api/me',{cache:'no-store'});if(!me.ok){location='/login.html';return}await loadSavedWallets();if(EthereumProvider&&typeof EthereumProvider.init==='function'){try{await initWalletConnect()}catch(e){els.project.textContent='WalletConnect unavailable';els.relay.textContent='Browser wallets still available';setMessage(`WalletConnect setup: ${e.message}`,true)}}else{els.project.textContent='WalletConnect library unavailable';els.relay.textContent='Direct browser wallets still available'}}catch(e){setMessage(e.message||String(e),true)}})();
})();